data_frames = {}
for model_name, json_str in data_str.items():
    data_list = json.loads(json_str)
    iterations = [item[1] for item in data_list]
    psnr_scores = [item[2] for item in data_list]
    data_frames[model_name] = pd.DataFrame({'Iteration': iterations, 'PSNR': psnr_scores})

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 10))
plt.style.use('seaborn-v0_8-whitegrid')

# --- entire training process ---
ax1.plot(data_frames['HAT_original']['Iteration'], data_frames['HAT_original']['PSNR'], label='HAT_original', color='royalblue')
ax1.plot(data_frames['HAT_RCF']['Iteration'], data_frames['HAT_RCF']['PSNR'], label='HAT_RCF', color='darkorange')
ax1.plot(data_frames['HAT_RCF_Layernorm']['Iteration'], data_frames['HAT_RCF_Layernorm']['PSNR'], label='HAT_RCF_Layernorm', color='forestgreen')
ax1.set_title('Overall PSNR Performance', fontsize=16, fontweight='bold')
ax1.set_xlabel('Iterations', fontsize=12)
ax1.set_ylabel('PSNR (dB)', fontsize=12)
ax1.legend(fontsize=11)
ax1.grid(True, which='both', linestyle='--', linewidth=0.5)

# --- zoomed in graph: early stage of training (0 ~ 40,000) ---
for model_name, df in data_frames.items():
    early_stage_df = df[df['Iteration'] <= 40000]
    if 'original' in model_name: color = 'royalblue'
    elif 'Layernorm' in model_name: color = 'forestgreen'
    else: color = 'darkorange'
    ax2.plot(early_stage_df['Iteration'], early_stage_df['PSNR'], label=model_name, color=color)

ax2.set_title('Zoom-in: Early Stage of Training (0-40k Iterations)', fontsize=16, fontweight='bold')
ax2.set_xlabel('Iterations', fontsize=12)
ax2.set_ylabel('PSNR (dB)', fontsize=12)
ax2.legend(fontsize=11)
ax2.grid(True, which='both', linestyle='--', linewidth=0.5)

plt.tight_layout()

file_name = 'figs/learning_graph/psnr_comparison_zoomed_graph.png'
plt.savefig(file_name, dpi=300)

print(f"graph saved to '{file_name}'")